// 선언: 이 이름의 함수가 int 두 개를 받고 int를 돌려줍니다.
int Add(int a, int b);

// 정의: 실제 계산할 본문을 제공합니다.
int Add(int a, int b) {
    return a + b;
}

// <limits>가 필요합니다. unsigned int의 실제 최댓값을 구합니다.
unsigned int value = std::numeric_limits<unsigned int>::max();
unsigned int wrapped = value + 1u;  // 부호 없는 연산 결과는 0입니다.

// 게임 규칙: 피해가 체력 이상이면 체력을 0으로 제한합니다.
unsigned int hp{3};
unsigned int damage{5};
hp = damage >= hp ? 0u : hp - damage;  // 먼저 비교해 큰 양수로 도는 일을 막습니다.

int a{1000};
int b{1000};
// a와 b를 먼저 int로 곱하고 나중에 저장 타입을 바꾸면 늦을 수 있습니다.
// 이 예에서는 곱하기 전에 한 피연산자를 long long으로 넓힙니다.
long long result = static_cast<long long>(a) * b;
// 넓은 타입도 유한합니다. 일반 입력은 그 결과 범위까지 검사해야 합니다.

// <cmath>가 필요합니다. 이 작은 수 예제만을 위한 절대 오차입니다.
bool close = std::abs((0.1 + 0.2) - 0.3) < 1e-12;
// 게임 전체의 모든 좌표·속도·시간 비교에 같은 값을 복사하지 않습니다.

int i{5};
int old = i++;  // 식의 결과는 증가 전 값 5. 이 문장 뒤 i는 6입니다.
int now = ++i;  // 먼저 i를 7로 증가시키고 그 값을 사용합니다.
// old = 5, now = 7, i = 7입니다. 한 식에서 여러 번 바꾸지 않습니다.

bool evaluated = false;
const bool result = false && (evaluated = true);
// 오른쪽 대입이 실행되지 않습니다: result와 evaluated는 모두 false입니다.

// <cstdint>가 필요합니다. std::uint32_t가 제공되는 환경을 사용합니다.
std::uint32_t flags{0};
constexpr std::uint32_t burning = std::uint32_t{1} << 2;

flags |= burning;                        // 켜기: 해당 자리를 1로 만듭니다.
bool is_burning = (flags & burning) != 0;  // 검사: 그 자리가 켜져 있나요?
flags &= ~burning;                        // 끄기: 해당 자리를 0으로 만듭니다.
flags ^= burning;                        // 뒤집기: 0이면 1, 1이면 0입니다.

// C++ 기초 01 · 원본 types.cpp의 실행 토큰을 유지한 한국어 주석판입니다.
// 공통 검사 함수는 original/src/check.hpp에 있습니다. C++20으로 함께 빌드합니다.
#include "check.hpp"
#include <climits>
#include <cmath>
#include <cstdint>
#include <limits>
#include <type_traits>

int main() {
    // 아래 네 조건은 컴파일할 때 검사합니다. Report()의 런타임 15회와 따로 셉니다.
    // sizeof의 단위는 char 한 개이고, 한 바이트의 비트 수는 CHAR_BIT로 확인합니다.
    static_assert(sizeof(char) == 1);
    static_assert(CHAR_BIT >= 8);
    static_assert(std::is_same_v<decltype(10.0), double>);
    static_assert(std::is_same_v<decltype(10.0f), float>);

    // 빈 중괄호는 int를 0으로 초기화합니다. 선언 뒤의 '='는 기존 객체에 새 값을 대입합니다.
    int zero{};
    int hp{100};
    hp = 80;
    CHECK(zero == 0);
    CHECK(hp == 80);

    // 0b 접두사는 2진수, 앞의 0은 8진수입니다. 비트 XOR는 서로 다른 비트만 1로 만듭니다.
    CHECK(0b00000010 == 2);
    CHECK((0b0100 ^ 0b0011) == 7);
    CHECK(0132 == 90);

    // 두 피연산자가 정수이면 정수 나눗셈입니다. 7.0을 쓰면 double 나눗셈이 됩니다.
    CHECK(7 / 2 == 3);
    CHECK(7.0 / 2 == 3.5);

    // 서로 다른 문장으로 분리해 증가 순서를 분명히 합니다. 후위는 이전 값, 전위는 증가한 값입니다.
    int i{5};
    const int old = i++;
    const int now = ++i;
    CHECK(old == 5);
    CHECK(now == 7);
    CHECK(i == 7);

    // unsigned의 모듈러 산술을 확인합니다. signed 정수의 넘침에도 같은 규칙이 적용되지는 않습니다.
    unsigned int n = std::numeric_limits<unsigned int>::max();
    CHECK(n + 1u == 0u);

    // 2번 비트 하나를 상태 플래그로 정합니다. OR로 켜고, 반전한 마스크와 AND하여 끕니다.
    std::uint32_t flags{0};
    constexpr std::uint32_t burning = std::uint32_t{1} << 2;
    flags |= burning;
    CHECK((flags & burning) != 0);
    flags &= ~burning;
    CHECK((flags & burning) == 0);

    // &&의 왼쪽이 false이면 오른쪽은 평가하지 않습니다. evaluated에 대입할 일도 없습니다.
    bool evaluated = false;
    const bool result = false && (evaluated = true);
    CHECK(!result && !evaluated);

    // 이진 부동소수점의 근삿값을 작은 절대 오차로 비교합니다. 모든 수치 문제의 공통 허용 오차는 아닙니다.
    CHECK(std::abs((0.1 + 0.2) - 0.3) < 1e-12);

    // 타입 크기는 실행 환경에서 관찰한 값입니다. 다른 플랫폼에서도 같은 크기라고 일반화하지 않습니다.
    std::cout << "CHAR_BIT=" << CHAR_BIT << " sizeof(int)=" << sizeof(int)
              << " sizeof(long)=" << sizeof(long) << " sizeof(void*)=" << sizeof(void*)
              << " sizeof(wchar_t)=" << sizeof(wchar_t) << '\n';
    Report();
}
